  2	
  3	import java.time.Clock;
  4	import java.time.Duration;
  5	import java.time.Instant;
  6	import java.time.temporal.ChronoUnit;
  7	import java.util.List;
  8	import java.util.UUID;
  9	
 10	import org.springframework.dao.DuplicateKeyException;
 11	import org.springframework.http.HttpStatus;
 12	import org.springframework.stereotype.Service;
 13	import org.springframework.transaction.PlatformTransactionManager;
 14	import org.springframework.transaction.support.TransactionTemplate;
 15	
 16	import br.com.loja.catalog.ProductRepository;
 17	import br.com.loja.checkout.CheckoutRequest;
 18	import br.com.loja.checkout.CheckoutService;
 19	import br.com.loja.checkout.OrderSummary;
 20	import br.com.loja.common.ApiException;
 21	import br.com.loja.common.ErrorCode;
 22	import br.com.loja.customer.CustomerRepository;
 23	
 24	@Service
 25	public class OrderService {
 26	
 27	    private static final String OK = "OK";
 28	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 29	
 30	    private final CheckoutService checkout;
 31	    private final OrderRepository orders;
 32	    private final ProductRepository products;
 33	    private final CustomerRepository customers;
 34	    private final List<OrderEventListener> listeners;
 35	    private final Clock clock;
 36	    private final TransactionTemplate tx;
 37	
 38	    OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
 39	                 CustomerRepository customers, List<OrderEventListener> listeners, Clock clock,
 40	                 PlatformTransactionManager transactionManager) {
 41	        this.checkout = checkout;
 42	        this.orders = orders;
 43	        this.products = products;
 44	        this.customers = customers;
 45	        this.listeners = listeners;
 46	        this.clock = clock;
 47	        this.tx = new TransactionTemplate(transactionManager);
 48	    }
 49	
 50	    public Order create(CheckoutRequest request) {
 51	        OrderSummary summary = checkout.summarize(request);
 52	        List<OrderItem> items = request.items().stream()
 53	                .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
 54	        Order order = new Order(UUID.randomUUID().toString(), request.customer().cpf(),
 55	                OrderStatus.AWAITING_PAYMENT, Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, items,
 56	                null, null, null);
 57	        try {
 58	            tx.executeWithoutResult(s -> customers.createIfAbsent(request.customer().cpf(), request.customer().email()));
 59	        } catch (DuplicateKeyException e) {
 60	            // outra máquina criou o mesmo cliente agora há pouco: está tudo certo
 61	        }
 62	        tx.executeWithoutResult(s -> orders.insert(order));
 63	        return order;
 64	    }
 65	
 66	    public Order get(String id) {
 67	        return orders.findById(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
 68	    }
 69	
 70	    private record PaymentResult(Order order, ErrorCode error) {
 71	    }
 72	
 73	    public Order confirmPayment(String id, String transactionId, String paidAtText) {
 74	        PaymentResult result = tx.execute(s -> processPayment(id, transactionId, paidAtText));
 75	        if (result.error() != null) {
 76	            throw new ApiException(result.error(), HttpStatus.CONFLICT);
 77	        }
 78	        return result.order();
 79	    }
 80	
 81	    private PaymentResult processPayment(String id, String transactionId, String paidAtText) {
 82	        Order order = lock(id);
 83	        Instant paidAt = parseInstant(paidAtText);
 84	        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
 85	            throw new ApiException(ErrorCode.INVALID_ORDER);
 86	        }
 87	        if (transactionId.equals(order.paymentTransactionId())) {
 88	            return outcomeOf(order, order.paymentOutcome());
 89	        }
 90	        requireMove(order, OrderStatus.PAID);
 91	
 92	        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
 93	            return failPayment(order, transactionId, ErrorCode.ORDER_EXPIRED);
 94	        }
 95	        if (!products.reserve(order.items())) {
 96	            return failPayment(order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
 97	        }
 98	        orders.recordPayment(id, transactionId, OK, OrderStatus.PAID);
 99	        Order paid = get(id);
100	        listeners.forEach(l -> l.onPaid(paid));
101	        return new PaymentResult(paid, null);
102	    }
103	
104	    private PaymentResult failPayment(Order order, String transactionId, ErrorCode error) {
105	        orders.recordPayment(order.id(), transactionId, error.name(), OrderStatus.CANCELLED);
106	        Order cancelled = get(order.id());
107	        listeners.forEach(l -> l.onCancelled(cancelled, false));
108	        return new PaymentResult(cancelled, error);
109	    }
110	
111	    private static PaymentResult outcomeOf(Order order, String outcome) {
112	        return new PaymentResult(order, OK.equals(outcome) ? null : ErrorCode.valueOf(outcome));
113	    }
114	
115	    public Order ship(String id, String trackingCode) {
116	        return tx.execute(s -> {
117	            Order order = lock(id);
118	            if (trackingCode == null || trackingCode.isBlank()) {
119	                throw new ApiException(ErrorCode.INVALID_ORDER);
120	            }
121	            requireMove(order, OrderStatus.SHIPPED);
122	            orders.recordShipment(id, trackingCode);
123	            Order shipped = get(id);
124	            listeners.forEach(l -> l.onShipped(shipped));
125	            return shipped;
126	        });
127	    }
128	
129	    public Order deliver(String id) {
130	        return tx.execute(s -> {
131	            Order order = lock(id);
132	            requireMove(order, OrderStatus.DELIVERED);
133	            orders.updateStatus(id, OrderStatus.DELIVERED);
134	            return get(id);
135	        });
136	    }
137	
138	    public Order cancel(String id) {
139	        return tx.execute(s -> {
140	            Order order = lock(id);
141	            requireMove(order, OrderStatus.CANCELLED);
142	            boolean wasPaid = order.status() == OrderStatus.PAID;
143	            if (wasPaid) {
144	                products.release(order.items());
145	            }
146	            orders.updateStatus(id, OrderStatus.CANCELLED);
147	            Order cancelled = get(id);
148	            listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
149	            return cancelled;
150	        });
151	    }
152	
153	    private Order lock(String id) {
154	        return orders.findByIdForUpdate(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
155	    }
156	
157	    private static void requireMove(Order order, OrderStatus target) {
158	        if (!order.status().canMoveTo(target)) {
159	            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED);
160	        }
161	    }
162	
163	    private static Instant parseInstant(String text) {
164	        try {
165	            return text == null ? null : Instant.parse(text);
166	        } catch (java.time.format.DateTimeParseException e) {
167	            return null;
168	        }
169	    }
170	}
