178	
179	import org.springframework.jdbc.core.simple.JdbcClient;
180	import org.springframework.stereotype.Repository;
181	
182	import br.com.loja.checkout.OrderSummary;
183	
184	@Repository
185	public class OrderRepository {
186	
187	    private static final String COLUMNS = """
188	            id, customer_cpf, status, created_at, tracking_code, payment_transaction_id, payment_outcome,
189	            products_subtotal, coupon_discount, shipping_cost, delivery_days, insurance, payment_adjustment,
190	            final_total, installments, installment_amount, next_purchase_credit, gift""";
191	
192	    private final JdbcClient jdbc;
193	
194	    OrderRepository(JdbcClient jdbc) {
195	        this.jdbc = jdbc;
196	    }
197	
198	    public void insert(Order o) {
199	        OrderSummary s = o.summary();
200	        jdbc.sql("""
201	                INSERT INTO orders (id, customer_cpf, status, created_at, products_subtotal, coupon_discount,
202	                    shipping_cost, delivery_days, insurance, payment_adjustment, final_total, installments,
203	                    installment_amount, next_purchase_credit, gift)
204	                VALUES (:id, :cpf, :status, :createdAt, :subtotal, :discount, :shipping, :days, :insurance,
205	                    :adjustment, :total, :installments, :installment, :credit, :gift)""")
206	                .param("id", o.id()).param("cpf", o.customerCpf()).param("status", o.status().name())
207	                .param("createdAt", OffsetDateTime.ofInstant(o.createdAt(), ZoneOffset.UTC))
208	                .param("subtotal", s.productsSubtotal()).param("discount", s.couponDiscount())
209	                .param("shipping", s.shippingCost()).param("days", s.deliveryDays())
210	                .param("insurance", s.insurance()).param("adjustment", s.paymentAdjustment())
211	                .param("total", s.finalTotal()).param("installments", s.installments())
212	                .param("installment", s.installmentAmount()).param("credit", s.nextPurchaseCredit())
213	                .param("gift", s.gift()).update();
214	        int line = 0;
215	        for (OrderItem item : o.items()) {
216	            jdbc.sql("INSERT INTO order_items (order_id, line_no, sku, quantity) VALUES (:id, :line, :sku, :q)")
217	                    .param("id", o.id()).param("line", line++).param("sku", item.sku())
218	                    .param("q", item.quantity()).update();
219	        }
220	    }
221	
222	    public Optional<Order> findById(String id) {
223	        return find("SELECT " + COLUMNS + " FROM orders WHERE id = :id", id);
224	    }
225	
226	    /** Trava a linha do pedido até o fim da transação (serializa operações entre as duas máquinas). */
227	    public Optional<Order> findByIdForUpdate(String id) {
228	        return find("SELECT " + COLUMNS + " FROM orders WHERE id = :id FOR UPDATE", id);
229	    }
230	
231	    private Optional<Order> find(String sql, String id) {
232	        return jdbc.sql(sql).param("id", id).query((rs, n) -> {
233	            List<OrderItem> items = jdbc
234	                    .sql("SELECT sku, quantity FROM order_items WHERE order_id = :id ORDER BY line_no")
235	                    .param("id", id).query((r, i) -> new OrderItem(r.getString("sku"), r.getInt("quantity")))
236	                    .list();
237	            OrderSummary summary = new OrderSummary(money(rs, "products_subtotal"), money(rs, "coupon_discount"),
238	                    money(rs, "shipping_cost"), rs.getInt("delivery_days"), money(rs, "insurance"),
239	                    money(rs, "payment_adjustment"), money(rs, "final_total"), rs.getInt("installments"),
240	                    money(rs, "installment_amount"), money(rs, "next_purchase_credit"), rs.getBoolean("gift"));
241	            Instant createdAt = rs.getObject("created_at", OffsetDateTime.class).toInstant();
242	            return new Order(rs.getString("id"), rs.getString("customer_cpf"),
243	                    OrderStatus.valueOf(rs.getString("status")), createdAt, summary, items,
244	                    rs.getString("tracking_code"), rs.getString("payment_transaction_id"),
245	                    rs.getString("payment_outcome"));
246	        }).optional();
247	    }
248	
249	    private static java.math.BigDecimal money(java.sql.ResultSet rs, String column) throws java.sql.SQLException {
250	        return rs.getBigDecimal(column).setScale(2);
251	    }
252	
253	    public void updateStatus(String id, OrderStatus status) {
254	        jdbc.sql("UPDATE orders SET status = :status WHERE id = :id")
255	                .param("status", status.name()).param("id", id).update();
256	    }
257	
258	    public void recordPayment(String id, String transactionId, String outcome, OrderStatus status) {
259	        jdbc.sql("""
260	                UPDATE orders SET status = :status, payment_transaction_id = :tx, payment_outcome = :outcome
261	                WHERE id = :id""")
262	                .param("status", status.name()).param("tx", transactionId).param("outcome", outcome)
263	                .param("id", id).update();
264	    }
265	
266	    public void recordShipment(String id, String trackingCode) {
267	        jdbc.sql("UPDATE orders SET status = :status, tracking_code = :code WHERE id = :id")
268	                .param("status", OrderStatus.SHIPPED.name()).param("code", trackingCode).param("id", id).update();
269	    }
270	
271	    /** Já comprou de verdade: tem pedido pago, enviado ou entregue (cancelado não conta). */
272	    public boolean hasPurchaseByCustomer(String cpf) {
273	        return jdbc.sql("""
274	                SELECT COUNT(*) FROM orders
275	                WHERE customer_cpf = :cpf AND status IN ('PAID', 'SHIPPED', 'DELIVERED')""")
276	                .param("cpf", cpf).query(Long.class).single() > 0;
277	    }
278	}

