    55	@Repository
    56	public class ProductRepository {
    57	
    58	    private final JdbcClient jdbc;
    59	
    60	    ProductRepository(JdbcClient jdbc) {
    61	        this.jdbc = jdbc;
    62	    }
    63	
    64	    public Optional<Product> findBySku(String sku) {
    65	        return jdbc.sql("SELECT sku, name, price, weight_kg, stock, discontinued FROM products WHERE sku = :sku")
    66	                .param("sku", sku)
    67	                .query((rs, n) -> new Product(rs.getString("sku"), rs.getString("name"),
    68	                        rs.getBigDecimal("price").setScale(2), rs.getBigDecimal("weight_kg").setScale(2),
    69	                        rs.getInt("stock"), rs.getBoolean("discontinued")))
    70	                .optional();
    71	    }
    72	
    73	    public List<Product> findAllBySkus(Collection<String> skus) {
    74	        return skus.stream().map(this::findBySku).flatMap(Optional::stream).toList();
    75	    }
    76	
    77	    /**
    78	     * Baixa o estoque de todos os itens ou de nenhum. Trava as linhas em ordem de SKU (evita deadlock entre
    79	     * duas máquinas) e só baixa se todas têm saldo; o UPDATE ainda protege com "stock >= quantidade".
    80	     * Precisa rodar dentro de uma transação.
    81	     */
    82	    public boolean reserve(List<OrderItem> items) {
    83	        List<OrderItem> sorted = items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
    84	        for (OrderItem item : sorted) {
    85	            Integer stock = jdbc.sql("SELECT stock FROM products WHERE sku = :sku FOR UPDATE")
    86	                    .param("sku", item.sku()).query(Integer.class).single();
    87	            if (stock < item.quantity()) {
    88	                return false;
    89	            }
    90	        }
    91	        for (OrderItem item : sorted) {
    92	            int updated = jdbc.sql("UPDATE products SET stock = stock - :q WHERE sku = :sku AND stock >= :q")
    93	                    .param("q", item.quantity()).param("sku", item.sku()).update();
    94	            if (updated != 1) {
    95	                throw new IllegalStateException("Estoque mudou durante a reserva de " + item.sku());
    96	            }
    97	        }
    98	        return true;
    99	    }
   100	
   101	    public void release(List<OrderItem> items) {
   102	        for (OrderItem item : items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList()) {
   103	            jdbc.sql("UPDATE products SET stock = stock + :q WHERE sku = :sku")
   104	                    .param("q", item.quantity()).param("sku", item.sku()).update();
   105	        }
   106	    }
   107	}
